package cn.mop.api;
import cn.mop.domain.DomainException;
import cn.mop.domain.search.*;
import cn.mop.domain.monitoring.MonitoringEventPipeline.*;
import cn.mop.domain.search.GlobalSearchRepository.*;
import org.junit.jupiter.api.Test;
import java.time.Instant;
import java.util.*;
import static org.junit.jupiter.api.Assertions.*;
class GlobalSearchQueryTest {
    @Test void contractGroupLimitsAreFiveFourThreeThree(){assertEquals(5,GlobalSearchQuery.ASSET_LIMIT);assertEquals(4,GlobalSearchQuery.EVENT_LIMIT);assertEquals(3,GlobalSearchQuery.TICKET_LIMIT);assertEquals(3,GlobalSearchQuery.AUTOMATION_LIMIT);}
    @Test void fullUnicodeQueryCountsCodePointsAndPreservesOriginalLiteral(){assertEquals("😀".repeat(100),new GlobalSearchQuery("😀".repeat(100)).text());assertEquals(" Ä%_ ",new GlobalSearchQuery(" Ä%_ ").text());assertThrows(DomainException.class,()->new GlobalSearchQuery("😀".repeat(101)));}
    @Test void emptyWhitespaceAndInvalidUnicodeNeverBecomeBrowseAll(){for(String value:Arrays.asList(null,""," \ufeff\u3000","x\n","x\u0085","x\ud800"))assertThrows(DomainException.class,()->new GlobalSearchQuery(value));}
    @Test void sqlSyntaxRemainsLiteralInput(){String query="x' OR '1'='1";assertEquals(query,new GlobalSearchQuery(query).text());}
    @Test void snapshotListsCannotBeMutatedByCaller(){var rows=new ArrayList<AssetHit>();rows.add(asset("1","tenant"));var snapshot=new Snapshot("x","tenant",Instant.EPOCH,"CURRENT_TENANT_INTERNAL",rows,false,List.of(),false,true,List.of(),false);rows.clear();assertEquals(1,snapshot.assets().size());assertThrows(UnsupportedOperationException.class,()->snapshot.assets().clear());}
    @Test void scopeDuplicateAndOverLimitSnapshotsFailClosed(){assertThrows(IllegalArgumentException.class,()->new Snapshot("x","tenant",Instant.EPOCH,"CURRENT_TENANT_INTERNAL",List.of(asset("1","foreign")),false,List.of(),false,true,List.of(),false));assertThrows(IllegalArgumentException.class,()->new Snapshot("x","tenant",Instant.EPOCH,"CURRENT_TENANT_INTERNAL",List.of(asset("1","tenant"),asset("1","tenant")),false,List.of(),false,true,List.of(),false));var rows=new ArrayList<AssetHit>();for(int i=0;i<6;i++)rows.add(asset(""+i,"tenant"));assertThrows(IllegalArgumentException.class,()->new Snapshot("x","tenant",Instant.EPOCH,"CURRENT_TENANT_INTERNAL",rows,false,List.of(),false,true,List.of(),false));}
    @Test void unknownVisibilityAndFalseOverflowAreRejected(){assertThrows(IllegalArgumentException.class,()->new Snapshot("x","tenant",Instant.EPOCH,"GLOBAL",List.of(),false,List.of(),false,true,List.of(),false));assertThrows(IllegalArgumentException.class,()->new Snapshot("x","tenant",Instant.EPOCH,"OWN_REPORT_REGISTRATIONS",List.of(),true,List.of(),false,true,List.of(),false));}
    @Test void reportHitsCannotClaimFormalWorkflowOrInvalidVersion(){assertThrows(IllegalArgumentException.class,()->new TicketHit("1","t","title","receipt","customer_report","CLOSED",1));assertThrows(IllegalArgumentException.class,()->new TicketHit("1","t","title","receipt","itsm","REGISTERED",1));assertThrows(IllegalArgumentException.class,()->new TicketHit("1","t","title","receipt","customer_report","REGISTERED",0));}
    EventHit event(String id,String tenant){return new EventHit(id,tenant,"RULE","合成事件",1,Severity.WARNING,MonitorState.PROBLEM,HandlingState.NEW,1,Instant.EPOCH);}
    Snapshot events(List<EventHit> rows,boolean more){return new Snapshot("x","tenant",Instant.EPOCH,"CURRENT_TENANT_INTERNAL",List.of(),false,List.of(),false,true,rows,more);}
    @Test void eventSnapshotsAreImmutableScopedDistinctAndBounded(){var rows=new ArrayList<EventHit>();rows.add(event("1","tenant"));var value=events(rows,false);rows.clear();assertEquals(1,value.events().size());assertThrows(UnsupportedOperationException.class,()->value.events().clear());assertThrows(IllegalArgumentException.class,()->events(List.of(event("1","foreign")),false));assertThrows(IllegalArgumentException.class,()->events(List.of(event("1","tenant"),event("1","tenant")),false));assertThrows(IllegalArgumentException.class,()->events(List.of(event("1","tenant")),true));assertThrows(IllegalArgumentException.class,()->events(java.util.stream.IntStream.range(0,5).mapToObj(i->event(""+i,"tenant")).toList(),false));}
    @Test void deniedEventsCannotCarryCountsRowsOrInternalReportVisibility(){assertThrows(IllegalArgumentException.class,()->new Snapshot("x","tenant",Instant.EPOCH,"OWN_REPORT_REGISTRATIONS",List.of(),false,List.of(),false,false,List.of(event("1","tenant")),false));assertThrows(IllegalArgumentException.class,()->new Snapshot("x","tenant",Instant.EPOCH,"OWN_REPORT_REGISTRATIONS",List.of(),false,List.of(),false,false,List.of(),true));assertThrows(IllegalArgumentException.class,()->new Snapshot("x","tenant",Instant.EPOCH,"CURRENT_TENANT_INTERNAL",List.of(),false,List.of(),false,false,List.of(),false));}
    @Test void eventHitRejectsMissingEnumsInvalidCountsVersionsAndOverlongRules(){assertThrows(IllegalArgumentException.class,()->new EventHit("1","t","R","N",1,null,MonitorState.PROBLEM,HandlingState.NEW,1,Instant.EPOCH));assertThrows(IllegalArgumentException.class,()->new EventHit("1","t","R","N",1,Severity.INFO,MonitorState.PROBLEM,HandlingState.NEW,0,Instant.EPOCH));assertThrows(IllegalArgumentException.class,()->new EventHit("1","t","R","N",0,Severity.INFO,MonitorState.PROBLEM,HandlingState.NEW,1,Instant.EPOCH));assertThrows(IllegalArgumentException.class,()->new EventHit("1","t","R","N",9_007_199_254_740_992L,Severity.INFO,MonitorState.PROBLEM,HandlingState.NEW,1,Instant.EPOCH));assertThrows(IllegalArgumentException.class,()->new EventHit("1","t","😀".repeat(65),"N",1,Severity.INFO,MonitorState.PROBLEM,HandlingState.NEW,1,Instant.EPOCH));assertThrows(IllegalArgumentException.class,()->new EventHit("1","t","R","😀".repeat(129),1,Severity.INFO,MonitorState.PROBLEM,HandlingState.NEW,1,Instant.EPOCH));}
    @Test void everyLegalEventStateRemainsRepresentable(){for(var severity:Severity.values())for(var monitor:MonitorState.values())for(var handling:HandlingState.values())assertNotNull(new EventHit("1","t","R","N",1,severity,monitor,handling,1,Instant.EPOCH));}
    AssetHit asset(String id,String tenant){return new AssetHit(id,tenant,"synthetic","router","manual",1);}
}
